CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE IF NOT EXISTS tenants(id text PRIMARY KEY,name text NOT NULL,active boolean NOT NULL DEFAULT true,created_at timestamptz NOT NULL);
CREATE TABLE IF NOT EXISTS users(id text PRIMARY KEY,tenant_id text NOT NULL REFERENCES tenants(id),email text NOT NULL UNIQUE,password_hash text NOT NULL,role text NOT NULL CHECK(role IN ('shipper','coordinator','ground_agent')),active boolean NOT NULL DEFAULT true,created_at timestamptz NOT NULL,deactivated_at timestamptz);
CREATE TABLE IF NOT EXISTS sessions(id text PRIMARY KEY,user_id text NOT NULL REFERENCES users(id),token_hash text NOT NULL UNIQUE,expires_at timestamptz NOT NULL,revoked_at timestamptz,created_at timestamptz NOT NULL);
CREATE INDEX IF NOT EXISTS sessions_user_idx ON sessions(user_id,expires_at);
CREATE TABLE IF NOT EXISTS flight_legs(id text PRIMARY KEY,tenant_id text NOT NULL REFERENCES tenants(id),flight_number text NOT NULL,origin text NOT NULL,destination text NOT NULL,departure_at timestamptz NOT NULL,arrival_at timestamptz NOT NULL,capacity_kg bigint NOT NULL CHECK(capacity_kg>0),reserved_kg bigint NOT NULL DEFAULT 0 CHECK(reserved_kg>=0),status text NOT NULL,version bigint NOT NULL DEFAULT 1,created_at timestamptz NOT NULL,UNIQUE(tenant_id,flight_number,departure_at));
CREATE INDEX IF NOT EXISTS legs_route_idx ON flight_legs(tenant_id,origin,destination,departure_at);
CREATE TABLE IF NOT EXISTS shipments(id text PRIMARY KEY,tenant_id text NOT NULL REFERENCES tenants(id),reference text NOT NULL,origin text NOT NULL,destination text NOT NULL,weight_kg bigint NOT NULL CHECK(weight_kg>0),pieces integer NOT NULL CHECK(pieces>0),status text NOT NULL,leg_id text REFERENCES flight_legs(id),idempotency_key text,version bigint NOT NULL DEFAULT 1,created_at timestamptz NOT NULL,updated_at timestamptz NOT NULL,UNIQUE(tenant_id,idempotency_key));
CREATE INDEX IF NOT EXISTS shipments_status_idx ON shipments(tenant_id,status,created_at,id);
CREATE TABLE IF NOT EXISTS customs_cases(id text PRIMARY KEY,shipment_id text NOT NULL UNIQUE REFERENCES shipments(id),status text NOT NULL,document_ref text NOT NULL,reviewed_by text REFERENCES users(id),updated_at timestamptz NOT NULL);
CREATE TABLE IF NOT EXISTS security_checks(id text PRIMARY KEY,shipment_id text NOT NULL UNIQUE REFERENCES shipments(id),status text NOT NULL,officer_id text REFERENCES users(id),notes text NOT NULL DEFAULT '',checked_at timestamptz);
CREATE TABLE IF NOT EXISTS handling_events(id text PRIMARY KEY,shipment_id text NOT NULL REFERENCES shipments(id),kind text NOT NULL,actor_id text NOT NULL REFERENCES users(id),occurred_at timestamptz NOT NULL,metadata jsonb NOT NULL DEFAULT '{}');
CREATE TABLE IF NOT EXISTS audit_events(id text PRIMARY KEY,tenant_id text NOT NULL REFERENCES tenants(id),actor_id text NOT NULL REFERENCES users(id),object_type text NOT NULL,object_id text NOT NULL,action text NOT NULL,result text NOT NULL,request_id text NOT NULL,occurred_at timestamptz NOT NULL);
CREATE INDEX IF NOT EXISTS audit_tenant_idx ON audit_events(tenant_id,occurred_at,id);
CREATE TABLE IF NOT EXISTS outbox_events(id text PRIMARY KEY,tenant_id text NOT NULL REFERENCES tenants(id),topic text NOT NULL,aggregate_id text NOT NULL,payload jsonb NOT NULL,attempts integer NOT NULL DEFAULT 0,available_at timestamptz NOT NULL,claimed_at timestamptz,published_at timestamptz,last_error text NOT NULL DEFAULT '');
CREATE INDEX IF NOT EXISTS outbox_ready_idx ON outbox_events(available_at) WHERE published_at IS NULL;
